import { useCallback, useId, useState } from 'react';
import { Button, Drawer } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface SideNavMenuProps {
  onNavigate: (key: NavKey) => void;
}

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNavMenu({ onNavigate }: SideNavMenuProps) {
  const [open, setOpen] = useState(false);
  const titleId = useId();

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <Button aria-expanded={open} aria-haspopup="menu" onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer
        open={open}
        side="left"
        onClose={() => setOpen(false)}
        aria-labelledby={titleId}
      >
        <nav className="jx-stack" style={{ gap: 'var(--jx-space-2)' }} aria-labelledby={titleId}>
          <h2 id={titleId} className="jx-drawer__title">
            Навигация
          </h2>

          {ITEMS.map((item) => (
            <Button key={item.key} variant="ghost" onClick={() => select(item.key)}>
              {item.label}
            </Button>
          ))}

          <div className="jx-divider" role="separator" />

          <Button variant="ghost" tone="danger" onClick={() => select('logout')}>
            Выйти
          </Button>
        </nav>
      </Drawer>
    </>
  );
}

